var state={route:location.hash.slice(1)||'welcome',store:'craft',tab:'Productos',category:'Todas',query:'',merchantRange:'Mes',frequency:'Mensual',minimum:50,scheduled:true,amount:25000,camera:null};
var $=function(s){return document.querySelector(s)};
var formatMoney=function(n,c){return new Intl.NumberFormat('es-CO',{style:'currency',currency:c||'COP',maximumFractionDigits:c==='USD'?2:0}).format(n)};
var getShop=function(id){return shops.find(function(s){return s.id===id})||shops[0]};
var globe='<img class="brand-logo" src="assets/lokora-logo-header.svg" alt="Lokora · go global, grow local">';
var icon=window.icon;
var image=function(src,alt,cls){return '<img class="'+(cls||'')+'" src="'+src+'" alt="'+(alt||'')+'" loading="lazy">'};
function toast(s){var t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(state.timer);state.timer=setTimeout(function(){t.classList.remove('show')},2300)}
function modal(title,text,button){var m=$('#modal');m.innerHTML='<div class="modal-card"><span class="eyebrow">LOKORA</span><h2>'+title+'</h2><p>'+text+'</p><button class="primary wide" data-modal-close>'+(button||'Entendido')+'</button></div>';m.classList.add('open');m.setAttribute('aria-hidden','false')}
function closeModal(){var m=$('#modal');m.classList.remove('open');m.setAttribute('aria-hidden','true')}
function heading(tag,title,sub){var secondary=['payment','stats','scheduled','settings','impactDetail','wallet'].indexOf(state.route)!==-1;return '<header class="screen-heading">'+(secondary?'<button class="page-back" data-action="back" aria-label="Volver">←</button>':'')+'<span class="eyebrow">'+tag+'</span><h1>'+title+'</h1>'+(sub?'<p>'+sub+'</p>':'')+'</header>'}
function header(){var hide=['welcome','scanner'].indexOf(state.route)!==-1;$('#appHeader').hidden=hide;if(hide)return;$('#appHeader').innerHTML='<a class="header-brand" href="#map" data-route="map">'+globe+'</a><div class="header-actions"><button class="location-button" data-route="map">⌖ Medellín, Colombia⌄</button><button class="wallet-chip" data-route="wallet"><span>▱</span><span><small>WALLET</small><b class="balance">$ 120 USD</b></span></button></div>'}
var navItems=[['explore','search','Explorar'],['map','pin','Mapa'],['coupons','ticket','Cupones'],['impact','people','Impacto'],['profile','user','Perfil']];
function nav(){var hidden=['welcome','scanner','payment','store','stats','scheduled','settings','impactDetail','wallet','seller','success'].indexOf(state.route)!==-1;$('#bottomNav').hidden=hidden;if(hidden)return;$('#bottomNav').innerHTML=navItems.map(function(x){return '<button class="nav-tab '+(state.route===x[0]?'active':'')+'" data-route="'+x[0]+'"><span class="nav-symbol">'+x[1]+'</span>'+x[2]+'</button>'}).join('')}
function shopCard(s){return '<button class="shop-card" data-store="'+s.id+'">'+image(s.logo,s.name+' · logo de tienda','shop-thumb shop-logo')+'<span class="shop-info"><span class="shop-title"><h3>'+s.name+'</h3><span class="rating">★ '+s.rating+' ('+s.reviews+')</span></span><span class="shop-category">'+s.category+' · '+s.type+'</span><span class="shop-distance">'+s.distance+' · '+s.area+'</span><span class="shop-price-row"><span class="shop-price">Desde '+formatMoney(s.price)+'</span><span class="pill">'+s.offer+'</span></span></span><span class="heart" data-favorite="'+s.id+'">♡</span></button>'}
function welcome(){return '<section class="splash"><div class="splash-brand">'+image('assets/lokora-logo-original.svg','Lokora · go global, grow local','welcome-logo')+'</div><div class="splash-copy"><h1>Descubre lo local.<br>Conecta sin fronteras.</h1><p>Negocios únicos, historias cercanas y pagos sencillos en cada viaje.</p></div><div class="splash-art">'+image('assets/medellin-mural.png','Mural de arte urbano de Medellín')+'</div><div class="splash-actions"><button class="primary wide" data-action="create">Crear cuenta</button><button class="secondary wide" data-action="login">Iniciar sesión</button></div><button class="guest-link" data-route="map">Continuar como visitante →</button></section>'}
function explore(){var q=state.query.toLocaleLowerCase('es');var list=shops.filter(function(s){return(state.category==='Todas'||s.category===state.category)&& (s.name+' '+s.category+' '+s.area).toLocaleLowerCase('es').indexOf(q)!==-1});return heading('MEDELLÍN, COLOMBIA','Descubre tiendas','Apoya el talento local en cada parada.')+'<label class="search-bar"><span>⌕</span><input id="shopSearch" value="'+state.query+'" placeholder="Buscar tiendas, productos o categorías"></label><div class="chips">'+['Todas','Gastronomía','Artesanías','Moda','Experiencias'].map(function(c){return '<button class="chip '+(state.category===c?'active':'')+'" data-category="'+c+'">'+c+'</button>'}).join('')+'</div><div class="section-heading"><h2>Tiendas cerca de ti</h2><button class="text-action" data-route="map">Ver mapa</button></div><div class="shop-list">'+(list.map(shopCard).join('')||'<p class="caption">No encontramos tiendas con ese nombre.</p>')+'</div>'}
function mapPage(){return heading('MEDELLÍN, COLOMBIA','Tiendas en el mapa','Descubre comercios locales y abre su catálogo.')+'<div class="map-wrap"><div id="googleMap" class="google-map-layer" aria-label="Mapa de tiendas de Medellín"></div><div class="map-controls"><label class="search-bar"><span>⌕</span><input id="mapSearch" aria-label="Buscar tiendas en el mapa" placeholder="Buscar tiendas o barrios"></label><button class="circle-btn" data-action="locate" aria-label="Centrar mapa en Medellín">◎</button></div><div class="map-tags">'+['Todas','Gastronomía','Artesanías','Moda','Experiencias'].map(function(x){return '<button class="chip '+((state.mapFilter||'Todas')===x?'active':'')+'" data-map-filter="'+x+'">'+x+'</button>'}).join('')+'</div><div class="map-credit" id="mapStatus" role="status">Cargando mapa de Medellín…</div><article class="map-sheet" id="mapShopSheet">'+mapSheetHTML(getShop(state.store))+'</article></div>'}
function mapSheetHTML(s){return image(s.logo,s.name+' · logo de tienda','map-shop-logo')+'<div class="map-sheet-body"><h3>'+s.name+'</h3><small>'+s.category+' · ★ '+s.rating+' ('+s.reviews+')</small><p class="map-address">'+s.area+'</p><div class="map-sheet-foot"><b>Desde '+formatMoney(s.price)+'</b><button class="primary wine" data-store="'+s.id+'">Ver tienda →</button></div></div>'}
function mapMatches(s){return (!state.mapFilter||state.mapFilter==='Todas'||s.category===state.mapFilter)&&(s.name+' '+s.category+' '+s.area+' '+s.products.map(function(p){return p[0]}).join(' ')).toLocaleLowerCase('es').indexOf((state.mapQuery||'').toLocaleLowerCase('es'))!==-1}
function selectMapShop(id){state.store=id;var sheet=$('#mapShopSheet');if(sheet){sheet.innerHTML=mapSheetHTML(getShop(id));applyLokoraIcons(sheet);sheet.classList.remove('sheet-pop');void sheet.offsetWidth;sheet.classList.add('sheet-pop')}document.querySelectorAll('.shop-map-pin').forEach(function(p){p.classList.toggle('selected',p.dataset.mapSelect===id)})}
function filterMapShops(){var list=shops.filter(mapMatches);shops.forEach(function(s){if(s.leafletMarker&&window.lokoraStreetMap){if(mapMatches(s))s.leafletMarker.addTo(window.lokoraStreetMap);else s.leafletMarker.remove()}if(s.marker&&window.lokoraMap)s.marker.setVisible(mapMatches(s))});var sheet=$('#mapShopSheet');if(sheet){sheet.hidden=!list.length;if(list.length&&!list.some(function(s){return s.id===state.store}))selectMapShop(list[0].id)}var status=$('#mapStatus');if(status)status.textContent=list.length+' tiendas de ejemplo · '+(window.lokoraMap?'Google Maps':'OpenStreetMap')}
function cleanupMap(){if(window.lokoraStreetMap){window.lokoraStreetMap.remove();window.lokoraStreetMap=null}window.lokoraMap=null;shops.forEach(function(s){s.leafletMarker=null;s.marker=null})}
function storePage(){var s=getShop(state.store),content='';if(state.tab==='Productos'){content='<div class="product-grid">'+s.products.map(function(p,i){return '<article class="product-card">'+image(s.productArt,p[0]+' · ilustración del producto')+'<div><b>'+p[0]+'</b><small>Producto local</small><strong>'+formatMoney(p[1])+'</strong></div></article>'}).join('')+'</div>'}else if(state.tab==='Información'){content='<div class="surface" style="padding:13px"><p class="caption">'+s.description+'</p><p class="caption" style="margin-top:10px">⌖ '+s.area+'</p><p class="caption" style="margin-top:8px">Horario · Hoy 9:00 a. m. – 7:00 p. m.</p></div>'}else{content='<article class="surface" style="padding:13px"><b style="font-size:10px">“Una experiencia hermosa y muy local.”</b><p class="caption" style="margin-top:6px">— Viajero Lokora · ★★★★★</p><p class="caption" style="margin-top:9px">Puntuación promedio '+s.rating+' basada en '+s.reviews+' reseñas.</p></article>'}return '<div class="shop-hero">'+'<div class="shop-hero-art shop-hero-art-'+s.id+'"><div class="brand-orbit"></div>'+image(s.logo,s.name+' · logo de tienda','store-logo-mark')+'</div><div class="hero-controls"><button class="icon-circle" data-route="map">←</button><button class="icon-circle" data-action="favorite">♡</button></div></div><section class="store-profile"><span class="eyebrow">'+s.category+' · '+s.distance+'</span><h1>'+s.name+'</h1><div class="rating">★ '+s.rating+' ('+s.reviews+' reseñas) · '+s.area+'</div><p class="description">'+s.description+'</p><div class="store-traits"><span class="store-trait"><b>'+s.emoji+'</b>Artesanal</span><span class="store-trait"><b>♡</b>Hecho local</span><span class="store-trait"><b>◉</b>Pago Lokora</span></div><div class="tab-row">'+['Productos','Información','Reseñas'].map(function(t){return '<button class="tab-link '+(state.tab===t?'active':'')+'" data-store-tab="'+t+'">'+t+'</button>'}).join('')+'</div>'+content+'<div class="input-row"><button class="secondary" data-action="add-cart">Agregar al carrito</button><button class="primary wine" data-route="scanner">Pagar con QR</button></div></section>'}
function couponsPage(){var arr=couponRows.filter(function(c){return !state.couponFilter||state.couponFilter==='Todos'||(state.couponFilter==='Cercanos'?getShop(c[0]).distance!=='3.2 km':getShop(c[0]).category===state.couponFilter)});return heading('BENEFICIOS LOCALES','Cupones para ti','Descubre ofertas en comercios locales.')+'<div class="coupon-banner"><div><small>AHORRA MIENTRAS DESCUBRES</small><h2>Más experiencias,<br>mejor precio.</h2><p>Activa el cupón y paga con Lokora.</p></div><span class="coupon-star">✳</span></div><div class="chips">'+['Todos','Cercanos','Gastronomía','Artesanías'].map(function(x){return '<button class="chip '+((state.couponFilter||'Todos')===x?'active':'')+'" data-coupon-filter="'+x+'">'+x+'</button>'}).join('')+'</div><div class="coupon-list">'+arr.map(function(c){var s=getShop(c[0]);return '<button class="coupon-card" data-store="'+s.id+'">'+image(s.logo,s.name+' · logo de tienda','coupon-logo')+'<span class="coupon-info"><h3>'+c[1]+'</h3><b>'+s.name+'</b><small>'+c[2]+'</small></span><span class="next">›</span></button>'}).join('')+'</div>'}
function qrSvg(){return '<svg viewBox="0 0 210 210" aria-label="Código QR de demostración"><rect width="210" height="210" fill="#fff"/><g fill="#101313"><path d="M9 9h58v58H9zm10 10v38h38V19zM22 22h32v32H22zM143 9h58v58h-58zm10 10v38h38V19zM156 22h32v32h-32zM9 143h58v58H9zm10 10v38h38v-38zM22 156h32v32H22zM82 8h13v13H82zM108 8h22v13h-22zM78 34h23v13H78zM108 30h13v27h-13zM128 38h14v14h-14zM79 61h13v13H79zM96 67h26v13H96zM136 72h15v14h-15zM76 88h15v15H76zM98 91h14v14H98zM119 87h13v29h-13zM145 93h14v14h-14zM168 82h17v14h-17zM191 85h13v24h-13zM80 112h25v13H80zM112 123h17v14h-17zM139 116h25v13h-25zM171 112h32v14h-32zM79 137h14v25H79zM99 144h20v14H99zM125 143h13v27h-13zM146 139h15v15h-15zM168 138h15v23h-15zM190 137h14v14h-14zM78 174h17v15H78zM101 168h14v28h-14zM124 177h14v15h-14zM145 167h24v14h-24zM178 171h26v13h-26zM147 190h14v13h-14zM169 191h15v12h-15zM190 190h14v13h-14z"/></g></svg>'}
function scanner(){return '<section class="scanner"><div class="scanner-top"><button class="circle-btn" data-route="map">←</button><button class="circle-btn" data-action="flash">⚡</button></div><h1 id="scannerTitle">Escanea el código QR<br>de la tienda</h1><div class="scan-frame" id="scanFrame">'+qrSvg()+'<div class="scan-laser"></div><video id="cameraVideo" autoplay playsinline class="hidden"></video></div><div class="scanner-actions"><button class="secondary" data-action="scan">Escanear QR</button><button class="primary" data-action="enter-amount">Ingresar monto</button></div><p class="helper" id="cameraHint">Apunta la cámara al código QR del comercio.</p></section>'}
function payment(){var s=getShop(state.store),n=Number(state.amount)||0;return heading('PAGO SEGURO','Enviar pago','Revisa el valor antes de confirmar.')+'<div class="surface payment-summary">'+image(s.logo,s.name+' · logo de tienda')+'<span><b>'+s.name+'</b><small>'+s.area+'</small></span><span class="rating">★ '+s.rating+'</span></div><label class="caption">MONTO A PAGAR · COP</label><div class="pay-amount"><span>$</span><input id="payAmount" type="number" min="0" step="1000" value="'+n+'"></div><div class="pay-currency"><span id="payEstimate">≈ USD '+(n/4000).toFixed(2)+'</span><select id="payCurrency"><option>COP</option><option>USD</option></select></div><label class="search-bar" style="margin-top:15px"><span>♧</span><input id="paymentNote" placeholder="Agregar nota (opcional)"></label><div class="section-heading"><h2>Resumen</h2></div><div class="surface summary-box"><div class="summary-row"><span>Monto</span><b id="paySummary">'+formatMoney(n)+'</b></div><div class="summary-row"><span>Comisión Lokora</span><b>'+formatMoney(0)+'</b></div><div class="summary-row total"><span>Total a pagar</span><b id="payTotal">'+formatMoney(n)+'</b></div><div class="summary-row"><span>Equivalente</span><span id="payUsd">≈ USD '+(n/4000).toFixed(2)+'</span></div></div><button class="primary wine wide" data-action="pay">Enviar pago</button><p class="secure-note">♙ Pago seguro · Protegido por Lokora</p>'}
function seller(){return '<div class="seller-welcome"><div><span class="eyebrow">PANEL DEL VENDEDOR</span><h1>Hola, Ana</h1><p class="caption">Artesanías Bacatá</p></div><button class="circle-btn" data-action="back">←</button></div><div class="segmented">'+['Hoy','Semana','Mes','Año'].map(function(x){return '<button class="segment '+(state.range===x?'active':'')+'" data-range="'+x+'">'+x+'</button>'}).join('')+'</div><article class="surface metric-card"><small>Ventas totales</small><strong>$ 3.450.000 <i style="font:500 9px Inter">COP</i></strong><span class="trend">↗ +22%</span></article><div class="seller-stats"><article class="surface metric-card"><small>Pagos recibidos</small><strong>56</strong><span class="trend">↗ +18%</span></article><article class="surface metric-card"><small>Clientes internacionales</small><strong>28</strong><span class="trend">↗ +35%</span></article></div><button class="primary wide" style="margin-top:13px" data-route="stats">Ver estadísticas</button><div class="section-heading"><h2>Atajos del negocio</h2></div><div class="shop-list"><button class="shop-card" data-route="scheduled"><span class="shop-info"><span class="shop-title"><h3>Pagos programados</h3><span>›</span></span><span class="shop-category">Configura la frecuencia de tus abonos</span></span></button><button class="shop-card" data-route="settings"><span class="shop-info"><span class="shop-title"><h3>Configuración de pagos</h3><span>›</span></span><span class="shop-category">Activa, pausa o ajusta tus pagos</span></span></button></div>'}
function chart(){var h=[22,28,34,29,46,38,53,48,60,68,56,74,66,82,76,95,82,100,90,112];return '<div class="chart"><svg viewBox="0 0 360 130" preserveAspectRatio="none"><path d="M10 115H350M10 80H350M10 45H350M10 10H350" fill="none" stroke="#e9e2d5" stroke-width="1"/>'+h.map(function(v,i){return '<rect x="'+(15+i*17)+'" y="'+(118-v)+'" width="9" height="'+v+'" rx="3" fill="'+(i>16?'#a12d4a':'#2e7d73')+'"/>'}).join('')+'<path d="M15 98C80 90 95 85 135 75S200 66 238 54 300 30 345 20" fill="none" stroke="#a12d4a" stroke-width="2"/></svg></div>'}
function stats(){return heading('RENDIMIENTO','Estadísticas de ventas','Últimos 30 días ⌄')+'<article class="surface metric-card"><small>Ventas</small><strong>$ 3.450.000 <i style="font:500 9px Inter">COP</i></strong><span class="trend">↗ +22%</span></article>'+chart()+'<div class="seller-stats"><article class="surface metric-card"><small>Pagos</small><strong>56</strong><span class="trend">↗ +18%</span></article><article class="surface metric-card"><small>Ticket promedio</small><strong>$ 61.607</strong><span class="trend">↗ +12%</span></article></div><div class="section-heading"><h2>Clientes por país</h2></div>'+[['🇺🇸','Estados Unidos','32%'],['🇲🇽','México','18%'],['🇪🇸','España','15%']].map(function(x){return '<div class="setting-row"><span>'+x[0]+' &nbsp;'+x[1]+'</span><div class="bar"><i style="width:'+x[2]+'"></i></div><b>'+x[2]+'</b></div>'}).join('')}
function scheduled(){return heading('TU NEGOCIO','Pagos programados','Recibe automáticamente tus fondos en los montos que elijas.')+'<div class="schedule-toggle"><b style="font-size:10px">Activar pagos programados</b><button class="toggle" role="switch" aria-checked="'+state.scheduled+'" data-action="toggle-scheduled"></button></div><div class="section-heading"><h2>Frecuencia</h2></div><div class="segmented">'+['Diaria','Semanal','Mensual'].map(function(x){return '<button class="segment '+(state.frequency===x?'active':'')+'" data-frequency="'+x+'">'+x+'</button>'}).join('')+'</div><label class="setting-row"><b>Monto mínimo</b><select id="minAmount">'+[25,50,75,100].map(function(x){return '<option value="'+x+'" '+(state.minimum===x?'selected':'')+'>'+x+' USD</option>'}).join('')+'</select></label><p class="caption" style="margin:8px 0">Cuando tu saldo disponible alcance este monto, se realizará el pago a tu cuenta bancaria.</p><div class="section-heading"><h2>Cuenta de destino</h2></div><div class="surface payment-summary"><span style="font-size:20px">▤</span><span><b>Bancolombia</b><small>Cuenta terminada en 1234</small></span><span>›</span></div><div class="info-box">ⓘ Los pagos se realizan a través de la red interoperable de Interledger.</div><button class="primary wide" data-action="save-schedule">Guardar cambios</button>'}
function settings(){return heading('CONFIGURACIÓN','Pagos y notificaciones','Administra cómo recibes tus pagos.')+'<div class="section-heading"><h2>Pagos programados</h2><button class="text-action" data-route="scheduled">Editar</button></div><div class="surface" style="padding:0 12px"><div class="setting-row"><b>Pagos programados</b><button class="toggle" role="switch" aria-checked="'+state.scheduled+'" data-action="toggle-scheduled"></button></div><div class="setting-row"><span>Monto mínimo</span><b>'+state.minimum+' USD ›</b></div><div class="setting-row"><span>Frecuencia</span><b>'+state.frequency+' ›</b></div><div class="setting-row"><span>Cuenta de destino</span><b>Bancolombia · 1234 ›</b></div></div><div class="section-heading"><h2>Notificaciones</h2></div><div class="surface" style="padding:0 12px">'+['Pago realizado','Saldo mínimo','Errores de pago'].map(function(x){return '<div class="setting-row"><span>'+x+'</span><button class="toggle" role="switch" aria-checked="true" data-action="toggle-setting"></button></div>'}).join('')+'</div><button class="outline wide" style="margin-top:18px" data-action="disable-schedule">Desactivar pagos programados</button>'}
function impact(){return heading('VIAJAR TAMBIÉN ES APORTAR','Tu impacto','Con tus compras impulsas comunidades locales 💛')+'<div class="impact-hero">'+image('assets/medellin-mural.png','Arte urbano de Medellín')+'<div><span class="eyebrow" style="color:#f0b429">ESTE VIAJE</span><b>Tu impacto contribuye a las comunidades locales.</b></div></div><div class="impact-grid"><article class="surface metric-card"><small>Tiendas apoyadas</small><strong>5</strong></article><article class="surface metric-card"><small>Gasto total</small><strong>$ 120 USD</strong></article><article class="surface metric-card"><small>Países visitados</small><strong>1</strong></article><article class="surface metric-card"><small>Emprendedores beneficiados</small><strong>12</strong></article></div><div class="section-heading"><h2>Tu impacto contribuye a:</h2></div><div class="impact-icons"><div class="impact-icon"><i>♧</i>Economía local</div><div class="impact-icon"><i>♙</i>Empleo</div><div class="impact-icon"><i>◈</i>Cultura viva</div><div class="impact-icon"><i>♻</i>Comercio sostenible</div></div><button class="primary wide" data-route="impactDetail">Ver detalle de impacto →</button>'}
function impactDetail(){var cats=[['Gastronomía',40,'#14524c'],['Artesanías',30,'#c84244'],['Moda',20,'#e6a53a'],['Otros',10,'#f0b429']];return heading('TU HUELLA LOCAL','Impacto de tu viaje','Compras que fortalecen las comunidades que visitas.')+'<div class="chips"><button class="chip active">Medellín, Colombia⌄</button><button class="chip">Últimos 7 días⌄</button></div><div class="section-heading"><h2>Distribución de tu gasto</h2></div><div class="surface" style="padding:15px"><div style="display:flex;align-items:center;gap:14px"><div class="donut"><span>$120<small>USD</small></span></div><div style="flex:1">'+cats.map(function(x){return '<div class="setting-row"><span><i style="display:inline-block;width:7px;height:7px;border-radius:50%;background:'+x[2]+';margin-right:5px"></i>'+x[0]+'</span><b>'+x[1]+'%</b></div>'}).join('')+'</div></div></div><div class="section-heading"><h2>Impacto por tienda</h2></div><div class="shop-list">'+shops.slice(0,4).map(function(s,i){return '<div class="shop-card">'+image(s.logo,s.name+' · logo de tienda','shop-thumb shop-logo')+'<span class="shop-info"><span class="shop-title"><h3>'+s.name+'</h3><b class="rating">$ '+[40,35,25,20][i]+' USD</b></span><span class="shop-category">'+s.category+'</span></span></div>'}).join('')+'</div>'}
function profile(){return heading('CUENTA LOKORA','Hola, Lucía','Tu viaje, tu wallet y tu impacto en un solo lugar.')+'<div class="surface payment-summary"><span class="profile-avatar">LM</span><span><b>Lucía Martínez</b><small>Viajera exploradora · USD</small></span><button class="text-action" data-action="edit-profile">Editar</button></div><div class="section-heading"><h2>Mi espacio</h2></div><div class="shop-list">'+[['wallet','Mi wallet','Saldo disponible · $120 USD'],['seller','Panel del vendedor','Gestiona tu tienda Lokora'],['stats','Estadísticas de ventas','Revisa tus resultados'],['scheduled','Pagos programados','Frecuencia y cuenta de abono'],['settings','Configuración de pagos','Ajusta pagos y notificaciones']].map(function(x){return '<button class="shop-card" data-route="'+x[0]+'"><span class="shop-info"><span class="shop-title"><h3>'+x[1]+'</h3><span>›</span></span><span class="shop-category">'+x[2]+'</span></span></button>'}).join('')+'</div><button class="outline wide" style="margin-top:16px" data-route="welcome">Cerrar sesión</button>'}
function wallet(){return heading('PAGA EN TU MONEDA','Mi wallet','Tu saldo disponible para comprar local.')+'<article class="surface metric-card wallet-card"><small>SALDO DISPONIBLE</small><strong>$ 120.00 <i>USD</i></strong><span>•••• &nbsp;•••• &nbsp;•••• &nbsp;2048</span></article><div class="section-heading"><h2>Conversión estimada</h2></div><div class="surface wallet-convert"><label class="caption">MONTO EN PESOS COLOMBIANOS</label><div class="input-row"><input id="walletAmount" type="number" min="0" value="85000"><b>COP</b></div><p class="caption" id="walletConversion">≈ $21.25 USD · Tasa de referencia</p><button class="primary wide" data-route="map">Explorar y pagar →</button></div><div class="section-heading"><h2>Movimientos recientes</h2></div><div class="setting-row"><span>Café Ancestral · Hoy</span><b>− $8.00 USD</b></div><div class="setting-row"><span>Artesanías Bacatá · Ayer</span><b>− $35.00 USD</b></div>'}
function success(){return '<section class="screen-heading success-screen"><span class="success-check">✓</span><h1>¡Pago enviado!</h1><p>Tu compra local está confirmada.<br>Gracias por apoyar a '+getShop(state.store).name+'.</p><div class="surface summary-box"><div class="summary-row"><span>Comercio</span><b>'+getShop(state.store).name+'</b></div><div class="summary-row"><span>Total</span><b>'+formatMoney(state.amount)+'</b></div><div class="summary-row"><span>Pagado en</span><b>Lokora wallet · USD</b></div></div><button class="primary wide" data-route="explore">Volver a explorar</button></section>'}
var pages={welcome:welcome,explore:explore,map:mapPage,store:storePage,coupons:couponsPage,scanner:scanner,payment:payment,seller:seller,stats:stats,scheduled:scheduled,settings:settings,impact:impact,impactDetail:impactDetail,profile:profile,wallet:wallet,success:success};
function render(){stopCamera();cleanupMap();var route=pages[state.route]?state.route:'explore';$('#appScreen').innerHTML=pages[route]();applyLokoraIcons($('#appScreen'));$('#appScreen').classList.toggle('splash-screen',route==='welcome');$('#appScreen').classList.toggle('map-screen',route==='map');header();nav();if(route==='map'){$('#mapSearch').value=state.mapQuery||'';loadMaps()}if(route==='wallet')wireWallet()}
function go(route){if(!pages[route]||route===state.route)return;var commit=function(){state.route=route;history.replaceState(null,'','#'+route);render();$('#appScreen').scrollTop=0;var view=$('#appScreen');if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)view.animate([{opacity:.55,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:330,easing:'cubic-bezier(.2,.75,.25,1)'});if(route==='map'&&window.lokoraStreetMap)requestAnimationFrame(function(){window.lokoraStreetMap.invalidateSize()})};if(document.startViewTransition&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.startViewTransition(commit)}else commit()}
function wireWallet(){var input=$('#walletAmount');if(input)input.oninput=function(){$('#walletConversion').textContent='≈ $'+((Number(input.value)||0)/4000).toFixed(2)+' USD · Tasa de referencia'}}
function loadMaps(){initStreetMap();var key=$('meta[name="google-maps-api-key"]').content;if(!key||key==='__GOOGLE_MAPS_API_KEY__')return;if(window.google&&window.google.maps){initGoogleMap();return}if(window.lokoraMapsLoading)return;window.lokoraMapsLoading=true;window.initLokoraMap=initGoogleMap;window.gm_authFailure=function(){window.lokoraMapsLoading=false;window.lokoraMap=null;initStreetMap();toast('La clave de Google Maps requiere revisión. Mostramos OpenStreetMap.')};var script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(key)+'&callback=initLokoraMap&loading=async&v=weekly';script.async=true;script.onerror=function(){window.lokoraMapsLoading=false;toast('Google Maps no está disponible. Mostramos OpenStreetMap.')};document.head.appendChild(script)}
function initStreetMap(){var el=$('#googleMap');if(!el||window.lokoraStreetMap)return;el.style.display='block';if(!window.L){$('#mapStatus').textContent='No se pudo cargar el mapa. Revisa tu conexión y recarga.';return}el.innerHTML='';var map=L.map(el,{zoomControl:false,scrollWheelZoom:true}).setView([6.2442,-75.5812],12);window.lokoraStreetMap=map;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>',maxZoom:19}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);shops.forEach(function(s){var icon=L.divIcon({className:'lokora-map-marker',html:'<button class="shop-map-pin '+(state.store===s.id?'selected':'')+'" data-map-select="'+s.id+'" aria-label="Ver '+s.name+'"><img src="'+s.logo+'" alt=""><b>'+formatMoney(s.price)+'</b></button>',iconSize:[100,48],iconAnchor:[50,48]});s.leafletMarker=L.marker([s.lat,s.lng],{icon:icon,keyboard:false,title:s.name}).addTo(map);s.leafletMarker.on('click',function(){selectMapShop(s.id)})});var bounds=L.latLngBounds(shops.map(function(s){return [s.lat,s.lng]}));map.fitBounds(bounds,{paddingTopLeft:[45,120],paddingBottomRight:[45,170],maxZoom:13});filterMapShops();requestAnimationFrame(function(){map.invalidateSize()})}
function initGoogleMap(){var el=$('#googleMap');if(!el||!window.google||!google.maps)return;if(window.lokoraStreetMap){window.lokoraStreetMap.remove();window.lokoraStreetMap=null}el.innerHTML='';el.style.display='block';var map=new google.maps.Map(el,{center:{lat:6.2442,lng:-75.5812},zoom:12,clickableIcons:false,mapTypeControl:false,streetViewControl:false,fullscreenControl:false,gestureHandling:'greedy',zoomControlOptions:{position:google.maps.ControlPosition.RIGHT_CENTER},styles:[{featureType:'poi',elementType:'labels',stylers:[{visibility:'off'}]},{featureType:'water',elementType:'geometry',stylers:[{color:'#c8dfdf'}]}]});window.lokoraMap=map;var bounds=new google.maps.LatLngBounds();shops.forEach(function(s){var marker=new google.maps.Marker({map:map,position:{lat:s.lat,lng:s.lng},title:s.name+' · ★ '+s.rating,label:{text:'$'+Math.round(s.price/1000)+' mil',color:'#1e3a52',fontWeight:'700',fontSize:'11px'},icon:{url:'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="76" height="40"><rect x="1" y="1" width="74" height="30" rx="15" fill="#fffdf7" stroke="#a12d4a" stroke-width="2"/><path d="M32 31l6 8 6-8" fill="#a12d4a"/></svg>'),scaledSize:new google.maps.Size(76,40),anchor:new google.maps.Point(38,40),labelOrigin:new google.maps.Point(38,16)}});marker.addListener('click',function(){selectMapShop(s.id)});s.marker=marker;bounds.extend(marker.getPosition())});map.fitBounds(bounds,{top:115,bottom:175,left:40,right:40});filterMapShops()}
function stopCamera(){if(state.camera){state.camera.getTracks().forEach(function(t){t.stop()});state.camera=null}}
async function startCamera(){if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){toast('La cámara no está disponible en este navegador.');return}try{state.camera=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});var v=$('#cameraVideo');v.srcObject=state.camera;v.classList.remove('hidden');$('#scannerTitle').textContent='Alinea el QR dentro del marco';$('#cameraHint').textContent='Cámara activa · acerca el código de la tienda.';toast('Cámara lista para escanear')}catch(e){toast('Permite el acceso a la cámara para escanear.')}} 
function doAction(a,b){if(a==='create')modal('Crear cuenta','El registro estará disponible cuando conectemos el servicio de autenticación.');else if(a==='login')modal('Iniciar sesión','El acceso estará disponible cuando conectemos el servicio de autenticación.');else if(a==='favorite')toast('Tienda guardada en tus favoritos.');else if(a==='add-cart')toast('Producto agregado al carrito de ejemplo.');else if(a==='locate'){if(window.lokoraMap)window.lokoraMap.panTo({lat:6.2442,lng:-75.5812});if(window.lokoraStreetMap)window.lokoraStreetMap.setView([6.2442,-75.5812],13);toast('Mapa centrado en Medellín.')}else if(a==='scan')startCamera();else if(a==='enter-amount'){stopCamera();go('payment')}else if(a==='flash')toast('Activa la cámara para usar la linterna.');else if(a==='pay'){go('success')}else if(a==='back'){var previous={payment:'scanner',stats:'seller',scheduled:'seller',settings:'seller',impactDetail:'impact',wallet:'profile',seller:'profile'}[state.route]||'explore';go(previous)}else if(a==='toggle-scheduled'){state.scheduled=!state.scheduled;render()}else if(a==='save-schedule'){state.minimum=Number($('#minAmount').value);toast('Configuración guardada.')}else if(a==='disable-schedule'){state.scheduled=false;render();toast('Pagos programados desactivados.')}else if(a==='toggle-setting'){b.setAttribute('aria-checked',b.getAttribute('aria-checked')!=='true');toast('Preferencia actualizada.')}else if(a==='seller-store')go('store');else if(a==='edit-profile')modal('Editar perfil','Aquí podrás actualizar tus datos y preferencias.')}
$('#appScreen').addEventListener('click',function(e){var favorite=e.target.closest('[data-favorite]');if(favorite){favorite.textContent=favorite.textContent==='♡'?'♥':'♡';favorite.style.color='#a12d4a';e.stopPropagation();return}var b=e.target.closest('button');if(!b)return;if(b.dataset.route){if(b.dataset.store)state.store=b.dataset.store;go(b.dataset.route);return}if(b.dataset.store){state.store=b.dataset.store;state.tab='Productos';go('store');return}if(b.dataset.action){doAction(b.dataset.action,b);return}if(b.dataset.category){state.category=b.dataset.category;render();return}if(b.dataset.storeTab){state.tab=b.dataset.storeTab;render();return}if(b.dataset.range){state.range=b.dataset.range;render();return}if(b.dataset.frequency){state.frequency=b.dataset.frequency;render();return}if(b.dataset.mapSelect){selectMapShop(b.dataset.mapSelect);return}if(b.dataset.mapFilter){state.mapFilter=b.dataset.mapFilter;document.querySelectorAll('[data-map-filter]').forEach(function(c){c.classList.toggle('active',c.dataset.mapFilter===state.mapFilter)});filterMapShops();return}if(b.dataset.couponFilter){state.couponFilter=b.dataset.couponFilter;render();return}if(b.dataset.modalClose){closeModal();return}});
$('#appScreen').addEventListener('input',function(e){if(e.target.id==='shopSearch'){state.query=e.target.value;var pos=$('#appScreen').scrollTop;var focusStart=e.target.selectionStart;render();$('#appScreen').scrollTop=pos;var input=$('#shopSearch');input.focus();input.setSelectionRange(focusStart,focusStart)}if(e.target.id==='mapSearch'){state.mapQuery=e.target.value;filterMapShops()}if(e.target.id==='payAmount'){state.amount=Number(e.target.value)||0;$('#payEstimate').textContent='≈ USD '+(state.amount/4000).toFixed(2);$('#payUsd').textContent='≈ USD '+(state.amount/4000).toFixed(2);$('#paySummary').textContent=formatMoney(state.amount);$('#payTotal').textContent=formatMoney(state.amount)}if(e.target.id==='walletAmount')wireWallet()});
$('#appScreen').addEventListener('change',function(e){if(e.target.id==='minAmount')state.minimum=Number(e.target.value);if(e.target.id==='payCurrency')state.currency=e.target.value});
$('#bottomNav').addEventListener('click',function(e){var b=e.target.closest('[data-route]');if(b)go(b.dataset.route)});
$('#appHeader').addEventListener('click',function(e){var b=e.target.closest('[data-route]');if(b){e.preventDefault();go(b.dataset.route)}});
$('#modal').addEventListener('click',function(e){if(e.target.id==='modal'||e.target.closest('[data-modal-close]'))closeModal()});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal()});
if(pages[location.hash.slice(1)])state.route=location.hash.slice(1);
render();
